    port: u16 = 8080,
    max_connections: usize = 1024,
    timeout_ms: u64 = 30000,
    require_api_key: bool = true,
};

pub const InferenceRequest = struct {
    prompt: []const u8,
    max_new_tokens: usize = 128,
    temperature: f64 = 0.7,
    top_p: f64 = 0.9,
    stream: bool = false,
};

pub const InferenceResponse = struct {
    text: []const u8,
    finish_reason: []const u8,
    usage: struct {
        prompt_tokens: usize,
        completion_tokens: usize,
        total_tokens: usize,
    },
};

// ============================================================================
// MODULE: SERVER IMPLEMENTATION
// ============================================================================

pub const Server = struct {
    allocator: Allocator,
    config: ServerConfig,
    core: *JaideCore.JaideCore,
    listener: net.Server,
    running: bool,

    pub fn init(allocator: Allocator, config: ServerConfig, core: *JaideCore.JaideCore) !Server {
        const address = try net.Address.parseIp("0.0.0.0", config.port);
        const listener = try address.listen(.{
            .reuse_address = true,
            .kernel_backlog = 128,
        });

        return Server{
            .allocator = allocator,
            .config = config,
            .core = core,
            .listener = listener,
            .running = false,
        };
    }

    pub fn deinit(self: *Server) void {
        self.listener.deinit();
    }

    pub fn start(self: *Server) !void {
        self.running = true;
        std.debug.print("ASI Inference Server listening on port {d}...\n", .{self.config.port});

        while (self.running) {
            const connection = try self.listener.accept();
            // Spawn thread for concurrent handling
            const thread = try std.Thread.spawn(.{}, handle_connection, .{ self, connection });
            thread.detach();
        }
    }

    fn handle_connection(self: *Server, connection: net.Server.Connection) void {
        defer connection.stream.close();

        var buffer: u8 = undefined;
        const bytes_read = connection.stream.read(&buffer) catch |err| {
            std.debug.print("Error reading stream: {}\n", .{err});
            return;
        };

        if (bytes_read == 0) return;

        // Minimal HTTP Parsing
        const raw_request = buffer[0..bytes_read];
        // Find double CRLF for body start
        const separator = "\r\n\r\n";
        const body_start_opt = std.mem.indexOf(u8, raw_request, separator);

        if (body_start_opt) |start_idx| {
            const body = raw_request[start_idx + 4 ..];
            self.process_request(connection, body) catch |err| {
                std.debug.print("Request processing error: {}\n", .{err});
                self.send_error(connection, 500, "Internal Server Error") catch {};
            };
        } else {
            self.send_error(connection, 400, "Bad Request - No Body") catch {};
        }
    }

    fn process_request(self: *Server, connection: net.Server.Connection, body: []const u8) !void {
