    fn asi_safety_audit(self: *Server, prompt: []const u8) bool {
        _ = self; // Suppress unused variable warning
        // Heuristic check defined in src/asi_alignment_governor.zig
        if (std.mem.indexOf(u8, prompt, "destroy") != null) return false;
        if (std.mem.indexOf(u8, prompt, "delete") != null) return false;
        if (std.mem.indexOf(u8, prompt, "override") != null) return false;
