        defer self.allocator.free(json_string);

        const header = try std.fmt.allocPrint(self.allocator, 
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {d}\r\n\r\n", 
            .{json_string.len}
        );
        defer self.allocator.free(header);

        try connection.stream.writeAll(header);
        try connection.stream.writeAll(json_string);
    }

    fn send_error(self: *Server, connection: net.Server.Connection, code: u16, msg: []const u8) !void {
        const response = try std.fmt.allocPrint(self.allocator,
            "HTTP/1.1 {d} Error\r\nContent-Type: text/plain\r\nContent-Length: {d}\r\n\r\n{s}",
            .{code, msg.len, msg}
        );
        defer self.allocator.free(response);
        try connection.stream.writeAll(response);
    }
